import { Injectable } from '@angular/core';
import { Location } from '@angular/common';
import { Router, NavigationEnd, NavigationExtras, UrlSerializer } from '@angular/router';

@Injectable()
export class NavigationService {
	private history: string[] = [];

	constructor(private router: Router, private location: Location, private urlSerializer: UrlSerializer) {
		this.router.events.subscribe((event) => {
			if (event instanceof NavigationEnd) {
				this.history.push(event.urlAfterRedirects);
			}
		});
	}

	public back(fallbackCommands?: any[], fallbackExtras?: NavigationExtras): void {
		this.history.pop();
		if (this.history.length > 0) {
			this.location.back();
		} else {
			if (fallbackCommands) {
				this.router.navigate(fallbackCommands, fallbackExtras);
			} else {
				this.router.navigateByUrl('/');
			}
		}
	}

	public previousRoute(fallbackRoute: string): string {
		const prevousRoute = this.history.at(-2);
		if (prevousRoute) {
			return prevousRoute;
		} else {
			return fallbackRoute;
		}
	}

	public findPastRoute(basicRoute: string): string {
		let queryParamRoute;

		for(let index = this.history.length -1; index >=0; index--) {
			const urltree = this.urlSerializer.parse(this.history[index]);
			if(basicRoute === '/' + urltree.root.children.primary?.toString()) {
				queryParamRoute = this.history[index];
				break;
			}
		}
		if (queryParamRoute) {
			return queryParamRoute;
		} else {
			return basicRoute;
		}
	}
}